@page "/courses"
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-4">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Title, code, or instructor" />
    </div>
    <div class="col-md-3">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <label for="minCredits" class="form-label">Min Credits</label>
        <input type="number" class="form-control" id="minCredits" name="minCredits" min="1" max="6"
               value="@MinCredits" />
    </div>
    <div class="col-md-2">
        <label for="maxCredits" class="form-label">Max Credits</label>
        <input type="number" class="form-control" id="maxCredits" name="maxCredits" min="1" max="6"
               value="@MaxCredits" />
    </div>
    <div class="col-md-1 d-flex align-items-end">
        <button type="submit" class="btn btn-primary">Filter</button>
    </div>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId, MinCredits, MaxCredits);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your criteria. Try adjusting your filters.</div>
}
else
{
    <p class="text-muted">@courses.Count course(s) found</p>

    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@course.Department.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Instructor.Name</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
    [SupplyParameterFromQuery] public int? MinCredits { get; set; }
    [SupplyParameterFromQuery] public int? MaxCredits { get; set; }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request. You will receive a confirmation once your request is processed.</p>

@if (Submitted)
{
    var selectedCourse = Catalog.GetCourse(Model.CourseId);
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>
            Thank you, <strong>@Model.Name</strong> (ID: @Model.StudentId).
            Your enrollment request for
            <strong>@(selectedCourse?.Code ?? "Unknown") — @(selectedCourse?.Title ?? "Unknown")</strong>
            has been received.
        </p>
        <hr />
        <p class="mb-0">You will receive a confirmation email once your request is reviewed.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="mb-3" style="max-width: 500px;">
            <label for="name" class="form-label">Full Name</label>
            <InputText id="name" class="form-control" @bind-Value="Model.Name" />
            <ValidationMessage For="() => Model.Name" />
        </div>

        <div class="mb-3" style="max-width: 500px;">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3" style="max-width: 500px;">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                <option value="0">— Select a course —</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}

